<?php $page_title='Sales & Analytics';require 'includes/header.php';$from=$_GET['from']??date('Y-m-d',strtotime('-29 days'));$to=$_GET['to']??date('Y-m-d');$s=$pdo->prepare("SELECT COALESCE(SUM(total),0) revenue,COUNT(*) orders,COALESCE(AVG(total),0) aov FROM orders WHERE order_status<>'cancelled' AND DATE(created_at) BETWEEN ? AND ?");$s->execute([$from,$to]);$m=$s->fetch();$s=$pdo->prepare("SELECT COALESCE(SUM(oi.quantity),0) items FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.order_status<>'cancelled' AND DATE(o.created_at) BETWEEN ? AND ?");$s->execute([$from,$to]);$items=(int)$s->fetch()['items'];$s=$pdo->prepare("SELECT DATE(created_at) d,SUM(total) revenue,COUNT(*) orders FROM orders WHERE order_status<>'cancelled' AND DATE(created_at) BETWEEN ? AND ? GROUP BY DATE(created_at) ORDER BY d");$s->execute([$from,$to]);$daily=$s->fetchAll();$max=max(array_map(fn($x)=>(float)$x['revenue'],$daily)?:[1]);$top=$pdo->query("SELECT oi.product_name,SUM(oi.quantity) sold,SUM(oi.subtotal) revenue FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.order_status<>'cancelled' GROUP BY oi.product_id,oi.product_name ORDER BY revenue DESC LIMIT 8")->fetchAll();$cats=$pdo->query("SELECT COALESCE(oi.category_name,'Uncategorized') category,SUM(oi.quantity) sold,SUM(oi.subtotal) revenue FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.order_status<>'cancelled' GROUP BY oi.category_name ORDER BY revenue DESC")->fetchAll();?>
<div class="page-head"><div><h1>Sales & Analytics</h1><p>All figures calculated from live MySQL order data.</p></div></div><div class="panel"><form class="filters"><label>From <input class="input" type="date" name="from" value="<?=$from?>"></label><label>To <input class="input" type="date" name="to" value="<?=$to?>"></label><button class="btn">Apply</button></form></div><div class="cards" style="margin-top:18px"><div class="stat"><div class="label">Revenue</div><div class="num"><?=money((float)$m['revenue'])?></div></div><div class="stat"><div class="label">Orders</div><div class="num"><?=$m['orders']?></div></div><div class="stat"><div class="label">Average Order Value</div><div class="num"><?=money((float)$m['aov'])?></div></div><div class="stat"><div class="label">Items Sold</div><div class="num"><?=$items?></div></div></div><div class="panel"><div class="panel-head"><h2>Daily sales</h2></div><div class="chart"><?php foreach($daily as $d):?><div class="bar" title="<?=date('M d',strtotime($d['d']))?> · <?=money((float)$d['revenue'])?>" style="height:<?=max(3,round(((float)$d['revenue']/$max)*100))?>%"><span><?=date('d',strtotime($d['d']))?></span></div><?php endforeach;?></div></div><div class="grid-2" style="margin-top:18px"><div class="panel"><h2>Product performance</h2><div class="table-wrap"><table><tr><th>Product</th><th>Sold</th><th>Revenue</th></tr><?php foreach($top as $x):?><tr><td><?=e($x['product_name'])?></td><td><?=$x['sold']?></td><td><?=money((float)$x['revenue'])?></td></tr><?php endforeach;?></table></div></div><div class="panel"><h2>Category performance</h2><div class="table-wrap"><table><tr><th>Category</th><th>Sold</th><th>Revenue</th></tr><?php foreach($cats as $x):?><tr><td><?=e($x['category'])?></td><td><?=$x['sold']?></td><td><?=money((float)$x['revenue'])?></td></tr><?php endforeach;?></table></div></div></div><?php require 'includes/footer.php';?>
